//! display/dc/inc/hw/abm.h + dce/dce_abm.h + dce/dmub_abm.c +
//! dce/dmub_abm_lcd.c (Linux 6.18.55), with the `abm_regs`/`abm_shift`/
//! `abm_mask` table of dcn21_resource.c: the adaptive backlight block, run by
//! the DMCUB when there is one. Its registers are programmed once at init;
//! everything after goes to the firmware as DMUB commands. The register
//! tables are machine-generated by `dcgen.py` from `ABM_DCN20_REG_LIST` /
//! `ABM_MASK_SH_LIST_DCN20`.
#![allow(dead_code)]

use crate::amdgpu_device::amdgpu_device;
use crate::dc::dc;
use crate::dc_helper::{reg_set, reg_update, reg_write};
use crate::regs::*;
use alloc::boxed::Box;

/// Which `abm_funcs` vtable `abm.funcs` points at.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum abm_funcs {
    dmub_abm_funcs,
}

/// `struct abm_funcs` (abm.h), the members ported.
#[derive(Default, Clone, Copy)]
pub struct abm_ops {
    pub abm_init: Option<fn(&amdgpu_device, &mut dc, u32, u32)>,
    pub set_abm_level: Option<fn(&amdgpu_device, &mut dc, u32) -> bool>,
    pub get_current_backlight: Option<fn(&amdgpu_device, &dc) -> u32>,
    pub get_target_backlight: Option<fn(&amdgpu_device, &dc) -> u32>,
    pub set_pipe_ex: Option<fn(&amdgpu_device, &mut dc, u32, u32, u32, u32) -> bool>,
    pub set_backlight_level_pwm: Option<fn(&amdgpu_device, &mut dc, u32, u32, u32, u32) -> bool>,
}

/// `abm_funcs` (dmub_abm.c), as far as ported.
const DMUB_ABM_FUNCS: abm_ops = abm_ops {
    abm_init: Some(dmub_abm_init_ex),
    set_abm_level: Some(dmub_abm_set_level_ex),
    get_current_backlight: Some(dmub_abm_get_current_backlight_ex),
    get_target_backlight: Some(dmub_abm_get_target_backlight_ex),
    set_pipe_ex: Some(dmub_abm_set_pipe_ex),
    set_backlight_level_pwm: Some(dmub_abm_set_backlight_level_pwm_ex),
};

impl abm_funcs {
    pub fn ops(self) -> &'static abm_ops {
        match self {
            abm_funcs::dmub_abm_funcs => &DMUB_ABM_FUNCS,
        }
    }
}

/// `struct dce_abm` (dce_abm.h) with its `struct abm` base. Linux' `ctx` is
/// not stored (see `clock_source`).
#[derive(Default)]
pub struct dce_abm {
    pub funcs: Option<abm_funcs>,
    pub dmcu_is_running: bool,
    pub regs: Option<&'static dce_abm_registers>,
    pub abm_shift: Option<&'static dce_abm_shift>,
    pub abm_mask: Option<&'static dce_abm_mask>,
}

impl dce_abm {
    /// `abm->funcs`.
    pub fn funcs(&self) -> &'static abm_ops {
        self.funcs.expect("abm funcs").ops()
    }

    fn rsm(&self) -> (&'static dce_abm_registers, &'static dce_abm_shift, &'static dce_abm_mask) {
        (self.regs.unwrap(), self.abm_shift.unwrap(), self.abm_mask.unwrap())
    }
}

/// `dmub_abm_construct` (dmub_abm.c).
fn dmub_abm_construct(abm_dce: &mut dce_abm, regs: &'static dce_abm_registers, abm_shift: &'static dce_abm_shift,
                      abm_mask: &'static dce_abm_mask) {
    abm_dce.funcs = Some(abm_funcs::dmub_abm_funcs);
    abm_dce.dmcu_is_running = false;

    abm_dce.regs = Some(regs);
    abm_dce.abm_shift = Some(abm_shift);
    abm_dce.abm_mask = Some(abm_mask);
}

/// `dmub_abm_create` (dmub_abm.c): only with DMCUB support.
pub fn dmub_abm_create(dmcub_support: bool, regs: &'static dce_abm_registers, abm_shift: &'static dce_abm_shift,
                       abm_mask: &'static dce_abm_mask) -> Option<Box<dce_abm>> {
    if dmcub_support {
        let mut abm_dce = Box::new(dce_abm::default());
        dmub_abm_construct(&mut abm_dce, regs, abm_shift, abm_mask);
        return Some(abm_dce);
    }
    None
}

/// `dmub_abm_init_ex` (dmub_abm.c).
fn dmub_abm_init_ex(adev: &amdgpu_device, dc: &mut dc, backlight: u32, user_level: u32) {
    dmub_abm_init(adev, dc, backlight, user_level);
}

/// `dmub_abm_get_current_backlight_ex` (dmub_abm.c); idle optimizations
/// are DCN 3.x's.
fn dmub_abm_get_current_backlight_ex(adev: &amdgpu_device, dc: &dc) -> u32 {
    dmub_abm_get_current_backlight(adev, dc)
}

/// `dmub_abm_get_target_backlight_ex` (dmub_abm.c).
fn dmub_abm_get_target_backlight_ex(adev: &amdgpu_device, dc: &dc) -> u32 {
    dmub_abm_get_target_backlight(adev, dc)
}

/// `abm_feature_support` (dmub_abm.c): ABM for the LCD of an eDP panel
/// instance.
fn abm_feature_support(dc: &dc, panel_inst: u32) -> u32 {
    let edp_num = crate::dc::dc_get_edp_links(dc).len() as u32;
    let mut ret = ABM_FEATURE_NO_SUPPORT;

    let mut i = 0;
    while i < edp_num {
        if panel_inst == i {
            break;
        }
        i += 1;
    }

    if i < edp_num {
        ret = ABM_LCD_SUPPORT;
    }

    ret
}

/// `dmub_abm_set_level_ex` (dmub_abm.c): the level for every eDP panel
/// that supports ABM.
fn dmub_abm_set_level_ex(adev: &amdgpu_device, dc: &mut dc, level: u32) -> bool {
    let mut ret = false;
    let mut panel_mask0: u8 = 0;

    for i in 0..MAX_NUM_EDP {
        let feature_support = abm_feature_support(dc, i);

        if feature_support == ABM_LCD_SUPPORT {
            panel_mask0 |= 0x01 << i;
        }
    }

    if panel_mask0 != 0 {
        ret = dmub_abm_set_level(adev, dc, level, panel_mask0);
    }

    ret
}

/// `dmub_abm_set_pipe_ex` (dmub_abm.c).
fn dmub_abm_set_pipe_ex(adev: &amdgpu_device, dc: &mut dc, otg_inst: u32, option: u32, panel_inst: u32,
                        pwrseq_inst: u32) -> bool {
    let mut ret = false;

    let feature_support = abm_feature_support(dc, panel_inst);

    if feature_support == ABM_LCD_SUPPORT {
        ret = dmub_abm_set_pipe(adev, dc, otg_inst, option, panel_inst, pwrseq_inst);
    }

    ret
}

/// `dmub_abm_set_backlight_level_pwm_ex` (dmub_abm.c).
fn dmub_abm_set_backlight_level_pwm_ex(adev: &amdgpu_device, dc: &mut dc, backlight_pwm_u16_16: u32, frame_ramp: u32,
                                       _controller_id: u32, panel_inst: u32) -> bool {
    let mut ret = false;

    let feature_support = abm_feature_support(dc, panel_inst);

    if feature_support == ABM_LCD_SUPPORT {
        ret = dmub_abm_set_backlight_level(adev, dc, backlight_pwm_u16_16, frame_ramp, panel_inst);
    }

    ret
}

/// `dmub_abm_get_current_backlight` (dmub_abm_lcd.c): the level in
/// hardware format, unsigned 17 bits with 1 integer and 16 fractional.
pub fn dmub_abm_get_current_backlight(adev: &amdgpu_device, dc: &dc) -> u32 {
    let regs = dc.res_pool.as_deref().and_then(|p| p.abm.as_deref()).expect("abm").rsm().0;
    crate::dc_helper::reg_read!(adev, regs, BL1_PWM_CURRENT_ABM_LEVEL)
}

/// `dmub_abm_get_target_backlight` (dmub_abm_lcd.c).
pub fn dmub_abm_get_target_backlight(adev: &amdgpu_device, dc: &dc) -> u32 {
    let regs = dc.res_pool.as_deref().and_then(|p| p.abm.as_deref()).expect("abm").rsm().0;
    crate::dc_helper::reg_read!(adev, regs, BL1_PWM_TARGET_ABM_LEVEL)
}

/// `dmub_abm_set_backlight_level` (dmub_abm_lcd.c).
pub fn dmub_abm_set_backlight_level(adev: &amdgpu_device, dc: &mut dc, backlight_pwm_u16_16: u32, frame_ramp: u32,
                                    panel_inst: u32) -> bool {
    let mut cmd = crate::dmub_srv::dmub_rb_cmd::default();
    cmd.set_header(DMUB_CMD__ABM, DMUB_CMD__ABM_SET_BACKLIGHT, SIZEOF_dmub_cmd_abm_set_backlight_data);
    cmd.0[ABMBL_FRAME_RAMP as usize..][..4].copy_from_slice(&frame_ramp.to_le_bytes());
    cmd.0[ABMBL_BACKLIGHT_USER_LEVEL as usize..][..4].copy_from_slice(&backlight_pwm_u16_16.to_le_bytes());
    cmd.0[ABMBL_VERSION as usize] = DMUB_CMD_ABM_CONTROL_VERSION_1 as u8;
    cmd.0[ABMBL_PANEL_MASK as usize] = 0x01 << panel_inst;

    crate::dc_dmub_srv::dc_wake_and_execute_dmub_cmd(adev, dc, &mut cmd, DM_DMUB_WAIT_TYPE_WAIT);

    true
}

/// `dmub_abm_set_level` (dmub_abm_lcd.c).
pub fn dmub_abm_set_level(adev: &amdgpu_device, dc: &mut dc, level: u32, panel_mask: u8) -> bool {
    let mut cmd = crate::dmub_srv::dmub_rb_cmd::default();
    cmd.set_header(DMUB_CMD__ABM, DMUB_CMD__ABM_SET_LEVEL, SIZEOF_dmub_cmd_abm_set_level_data);
    cmd.0[ABMLEVEL_LEVEL as usize..][..4].copy_from_slice(&level.to_le_bytes());
    cmd.0[ABMLEVEL_VERSION as usize] = DMUB_CMD_ABM_CONTROL_VERSION_1 as u8;
    cmd.0[ABMLEVEL_PANEL_MASK as usize] = panel_mask;

    crate::dc_dmub_srv::dc_wake_and_execute_dmub_cmd(adev, dc, &mut cmd, DM_DMUB_WAIT_TYPE_WAIT);

    true
}

/// `dmub_abm_set_pipe` (dmub_abm_lcd.c).
pub fn dmub_abm_set_pipe(adev: &amdgpu_device, dc: &mut dc, otg_inst: u32, option: u32, panel_inst: u32,
                         pwrseq_inst: u32) -> bool {
    let ramping_boundary: u8 = 0xFF;

    let mut cmd = crate::dmub_srv::dmub_rb_cmd::default();
    cmd.set_header(DMUB_CMD__ABM, DMUB_CMD__ABM_SET_PIPE, SIZEOF_dmub_cmd_abm_set_pipe_data);
    cmd.0[ABMPIPE_OTG_INST as usize] = otg_inst as u8;
    cmd.0[ABMPIPE_PWRSEQ_INST as usize] = pwrseq_inst as u8;
    cmd.0[ABMPIPE_SET_PIPE_OPTION as usize] = option as u8;
    cmd.0[ABMPIPE_PANEL_INST as usize] = panel_inst as u8;
    cmd.0[ABMPIPE_RAMPING_BOUNDARY as usize] = ramping_boundary;

    crate::dc_dmub_srv::dc_wake_and_execute_dmub_cmd(adev, dc, &mut cmd, DM_DMUB_WAIT_TYPE_WAIT);

    true
}

/// `dmub_abm_enable_fractional_pwm` (dmub_abm_lcd.c): tell the firmware
/// whether the backlight PWM may use a fractional duty cycle, for every
/// eDP panel instance.
fn dmub_abm_enable_fractional_pwm(adev: &amdgpu_device, dc: &mut dc) {
    let fractional_pwm: u32 = if !dc.config.disable_fractional_pwm { 1 } else { 0 };
    let edp_id_count = dc.ctx.dc_edp_id_count;
    let mut panel_mask: u8 = 0;

    for i in 0..edp_id_count {
        panel_mask |= 0x01 << i;
    }

    let mut cmd = crate::dmub_srv::dmub_rb_cmd::default();
    cmd.set_header(DMUB_CMD__ABM, DMUB_CMD__ABM_SET_PWM_FRAC, SIZEOF_dmub_cmd_abm_set_pwm_frac_data);
    cmd.0[ABMFRAC_FRACTIONAL_PWM as usize..][..4].copy_from_slice(&fractional_pwm.to_le_bytes());
    cmd.0[ABMFRAC_VERSION as usize] = DMUB_CMD_ABM_CONTROL_VERSION_1 as u8;
    cmd.0[ABMFRAC_PANEL_MASK as usize] = panel_mask;

    crate::dc_dmub_srv::dc_wake_and_execute_dmub_cmd(adev, dc, &mut cmd, DM_DMUB_WAIT_TYPE_WAIT);
}

/// `dmub_abm_init` (dmub_abm_lcd.c): the histogram and sample-rate setup,
/// the backlight levels the panel has now, then the fractional PWM command.
pub fn dmub_abm_init(adev: &amdgpu_device, dc: &mut dc, backlight: u32, user_level: u32) {
    let c = dc.res_pool.as_deref().and_then(|p| p.abm.as_deref()).expect("abm").rsm();
    let regs = c.0;

    reg_write!(adev, regs, DC_ABM1_HG_SAMPLE_RATE, 0x3);
    reg_write!(adev, regs, DC_ABM1_HG_SAMPLE_RATE, 0x1);
    reg_write!(adev, regs, DC_ABM1_LS_SAMPLE_RATE, 0x3);
    reg_write!(adev, regs, DC_ABM1_LS_SAMPLE_RATE, 0x1);
    reg_write!(adev, regs, BL1_PWM_BL_UPDATE_SAMPLE_RATE, 0x1);

    reg_set!(adev, c, DC_ABM1_HG_MISC_CTRL, 0, ABM1_HG_NUM_OF_BINS_SEL, 0, ABM1_HG_VMAX_SEL, 1,
        ABM1_HG_BIN_BITWIDTH_SIZE_SEL, 0);

    reg_set!(adev, c, DC_ABM1_IPCSC_COEFF_SEL, 0, ABM1_IPCSC_COEFF_SEL_R, 2, ABM1_IPCSC_COEFF_SEL_G, 4,
        ABM1_IPCSC_COEFF_SEL_B, 2);

    reg_update!(adev, c, BL1_PWM_CURRENT_ABM_LEVEL, BL1_PWM_CURRENT_ABM_LEVEL, backlight);

    reg_update!(adev, c, BL1_PWM_TARGET_ABM_LEVEL, BL1_PWM_TARGET_ABM_LEVEL, backlight);

    reg_update!(adev, c, BL1_PWM_USER_LEVEL, BL1_PWM_USER_LEVEL, user_level);

    reg_update!(adev, c, DC_ABM1_LS_MIN_MAX_PIXEL_VALUE_THRES, ABM1_LS_MIN_PIXEL_VALUE_THRES, 0,
        ABM1_LS_MAX_PIXEL_VALUE_THRES, 1000);

    reg_set!(adev, c, DC_ABM1_HGLS_REG_READ_PROGRESS, 0, ABM1_HG_REG_READ_MISSED_FRAME_CLEAR, 1,
        ABM1_LS_REG_READ_MISSED_FRAME_CLEAR, 1, ABM1_BL_REG_READ_MISSED_FRAME_CLEAR, 1);

    dmub_abm_enable_fractional_pwm(adev, dc);
}

/// `struct dmub_psr` (dmub_psr.h). Its ops send DMUB commands and join with
/// the PSR enable path.
#[derive(Default)]
pub struct dmub_psr {}

/// `dmub_psr_create` (dmub_psr.c).
pub fn dmub_psr_create() -> Box<dmub_psr> {
    Box::new(dmub_psr {})
}

